64	const sumOf = <T>(values: readonly T[], amountOf: (value: T) => number): number =>
65	  values.reduce((sum, value) => sum + amountOf(value), 0);
66	
67	const isKnownItemType = (type: string): boolean =>
68	  type in BASE_PREMIUM_BY_ITEM_TYPE;
69	
70	const rejectUnknownItemTypes = (items: readonly Item[]): void => {
71	  const unknownItem = items.find((item) => !isKnownItemType(item.type));
72	
73	  if (unknownItem !== undefined) {
74	    throw new Error(`Unknown item type: ${unknownItem.type}`);
75	  }
76	};
