169	const PROCESSING_FEE = 5;
170	
171	const quotePremiumOf = (
172	  items: readonly Item[],
173	  customer: Customer,
174	  previousQuoteCount: number,
175	): number => {
176	  rejectUnknownItemTypes(items);
