255	// The state a scenario carries from one step to the next: the results produced
256	// so far, and how much of each policy's cap is still available.
257	interface ScenarioState {
258	  readonly results: readonly StepResult[];
259	  readonly remainingCaps: readonly number[];
260	}
261	
262	const initialStateOf = (policies: readonly QuoteStep[]): ScenarioState => ({
263	  results: [],
264	  remainingCaps: policies.map((policy) => capOf(policy.items)),
265	});
266	
267	const capsAfterClaim = (
268	  remainingCaps: readonly number[],
269	  policy: number,
270	  remainingCap: number,
271	): readonly number[] =>
272	  remainingCaps.map((cap, index) => (index === policy ? remainingCap : cap));
273	
274	const stateAfterQuote = (
275	  state: ScenarioState,
276	  result: QuoteResult,
277	): ScenarioState => ({ ...state, results: [...state.results, result] });
278	
279	const stateAfterClaim = (
280	  state: ScenarioState,
281	  step: ClaimStep,
282	  result: ClaimResult,
283	): ScenarioState => ({
284	  results: [...state.results, result],
285	  remainingCaps: capsAfterClaim(
286	    state.remainingCaps,
287	    step.policy,
288	    result.remainingCap,
289	  ),
290	});
