292	export const runScenario = (scenario: Scenario): ScenarioResult => {
293	  const policies = quoteStepsOf(scenario.steps);
294	
295	  const { results } = scenario.steps.reduce(
296	    (state, step, stepIndex) =>
297	      isQuoteStep(step)
