299	            state,
300	            quoteResultOf(
301	              step,
302	              scenario.customer,
303	              quoteStepsBefore(scenario.steps, stepIndex),
304	            ),
305	          )
306	        : stateAfterClaim(
307	            state,
308	            step,
309	            claimResultOf(step, policies, state.remainingCaps[step.policy]),
310	          ),
311	    initialStateOf(policies),
312	  );
313	
314	  return { results };
315	};
